export function Margin({
  top = {{top}},
  right = {{right}},
  bottom = {{bottom}},
  left = {{left}},
}) {
  return (
    <div style={{ font: "13px/1.4 system-ui, sans-serif", color: "#241430", width: 300 }}
      role="img" aria-label="A box pushed away from its container edges by margin on each side, shown in sky blue">
      <div style={{ background: "#BFD9F2", borderRadius: 8, padding: 2 }}>
        <div style={{ background: "#A8E6C1", borderRadius: 6, padding: 14, fontWeight: 700, textAlign: "center", boxSizing: "border-box",
          margin: `${top}px ${right}px ${bottom}px ${left}px` }}>
          content
        </div>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>margin: {top}px {right}px {bottom}px {left}px (top right bottom left)</p>
    </div>
  );
}
